INTEGRATION_SQL = "-- Target: kotoba_app / keewulninyoeylgflshb. Only the kotoba writer function.\nbegin;\ncreate or replace function public.chokomana_commit_learning_events_v1(p_device_hash text,p_writer_id uuid,p_expected_revision bigint,p_state jsonb,p_events jsonb,p_active boolean)\nreturns bigint language plpgsql security invoker set search_path='' as $$\ndeclare v_profile text; v_revision bigint; e jsonb; existing public.chokomana_learning_events%rowtype; aid uuid; st jsonb; en public.chokomana_learning_events%rowtype; v_count int; v_correct int; v_positions int; v_total int; cat jsonb;\nbegin\n select profile_id::text into v_profile from public.chokomana_device_links where device_hash=p_device_hash and source_app='kotoba';\n if v_profile is null then raise exception 'unverified profile' using errcode='42501'; end if;\n if jsonb_typeof(p_events)<>'array' or jsonb_array_length(p_events)>100 then raise exception 'invalid event batch'; end if;\n perform pg_advisory_xact_lock(hashtextextended(v_profile||':kotoba',0));\n if exists(select 1 from public.chokomana_learning_leases where profile_id=v_profile and source_app='kotoba' and writer_id<>p_writer_id and expires_at>now()) then raise exception 'another learning tab is active' using errcode='55P03'; end if;\n if p_expected_revision is null then\n insert into public.chocomana_state(profile_id,payload,revision,updated_at) values(v_profile,p_state,1,now()) on conflict(profile_id) do nothing returning revision into v_revision;\n else\n update public.chocomana_state set payload=p_state,revision=p_expected_revision+1,updated_at=now() where profile_id=v_profile and revision=p_expected_revision returning revision into v_revision;\n end if;\n if v_revision is null then raise exception 'state revision conflict' using errcode='40001'; end if;\n if p_active then insert into public.chokomana_learning_leases values(v_profile,'kotoba',p_writer_id,now()+interval '45 seconds') on conflict(profile_id,source_app) do update set writer_id=excluded.writer_id,expires_at=excluded.expires_at;\n else update public.chokomana_learning_leases set expires_at=now() where profile_id=v_profile and source_app='kotoba' and writer_id=p_writer_id; end if;\n for e in select value from jsonb_array_elements(p_events) loop\n if e->>'profile_id'<>v_profile or e->>'source_app'<>'kotoba' then raise exception 'event owner mismatch' using errcode='42501'; end if;\n select * into existing from public.chokomana_learning_events where event_id=(e->>'event_id')::uuid;\n if found then\n  if existing.profile_id<>v_profile or existing.source_app<>'kotoba' or existing.event_hash<>e->>'event_hash' then raise exception 'event_id content mismatch' using errcode='23505'; end if;\n  continue;\n end if;\n insert into public.chokomana_learning_events(schema_version,event_id,profile_id,source_app,app_version,content_version,attempt_id,occurrence_id,question_id,segment_id,sequence,occurred_at,event_type,payload,event_hash)\n values(1,(e->>'event_id')::uuid,v_profile,'kotoba',e->>'app_version',e->>'content_version',(e->>'attempt_id')::uuid,(e->>'occurrence_id')::uuid,e->>'question_id',(e->>'segment_id')::uuid,(e->>'sequence')::int,(e->>'occurred_at')::timestamptz,e->>'event_type',e->'payload',e->>'event_hash');\n end loop;\n -- Completion may arrive before earlier batches. Recheck touched attempts every time.\n for aid in select distinct (x->>'attempt_id')::uuid from jsonb_array_elements(p_events) x loop\n select payload into st from public.chokomana_learning_events where profile_id=v_profile and source_app='kotoba' and attempt_id=aid and event_type='session_started' order by occurred_at,sequence limit 1;\n select * into en from public.chokomana_learning_events where profile_id=v_profile and source_app='kotoba' and attempt_id=aid and event_type='session_ended' and payload->>'status'='completed' order by occurred_at,sequence limit 1;\n if st is null or en.event_id is null or coalesce(st->>'mode','') not in ('challenge','review') or (st->>'planned_question_count')::int not in (4,6,8,12) then continue; end if;\n v_total:=(st->>'planned_question_count')::int;\n if (en.payload->>'planned_question_count')::int<>v_total or (en.payload->>'answered_count')::int<>v_total then continue;end if;\n with roots as(select occurrence_id,(payload->>'position')::int position from public.chokomana_learning_events where profile_id=v_profile and source_app='kotoba' and attempt_id=aid and event_type='item_presented' and payload->>'parent_occurrence_id' is null),firsts as(select r.position,f.payload from roots r join public.chokomana_learning_events f on f.profile_id=v_profile and f.source_app='kotoba' and f.attempt_id=aid and f.occurrence_id=r.occurrence_id and f.event_type='response_submitted' and (f.payload->>'response_index')::int=1)\n select count(*),count(*) filter(where payload->>'is_correct'='true'),count(distinct position) filter(where position between 1 and v_total) into v_count,v_correct,v_positions from firsts;\n if v_count<>v_total or v_positions<>v_total then continue; end if;\n select payload into cat from public.chokomana_learning_catalog where source_app='kotoba' and entry_type='menu' and entry_id=st->>'menu_id' and content_version=en.content_version limit 1;\n if cat is null or not coalesce((cat->'question_count_options') @> to_jsonb(v_total),false) then continue;end if;\n insert into public.chokomana_stamps(profile_id,source_app,attempt_id,category_key,category_label,stamp_char,reading,difficulty,correct_count,total_count,grade,finished_at)\n values(v_profile,'kotoba',aid::text,cat->>'category_id',cat->>'category_label',cat->>'stamp_char',cat->>'reading',st->>'difficulty_id',v_correct,v_total,case when v_correct=v_total and st->>'mode'='challenge' then 'gold' else 'white' end,en.occurred_at)\n on conflict(profile_id,source_app,attempt_id) do nothing;\n end loop;\n return v_revision;\nend $$;\nrevoke all on function public.chokomana_commit_learning_events_v1(text,uuid,bigint,jsonb,jsonb,boolean) from public,anon,authenticated;\ngrant execute on function public.chokomana_commit_learning_events_v1(text,uuid,bigint,jsonb,jsonb,boolean) to service_role;\ncommit;\n"
INTEGRATION_HELP = 'ことば ver.27：短い説明(explain)と言葉の意味(meaning)を一時停止。反対語は維持。表示メニューは9種類×3難易度、出題対象2412問。既存3132問分の教材と過去記録は削除せず保持。停止した内容の新規開始・苦手練習・直接起動・途中再開を抑止。集約用台帳は新しい版で対象メニューをis_active=falseとし、本人確認後に既存の非同期登録を開始する。DB構造・SQL・Secrets・起動方式は変更なし。以下は過去版の連携資料。\n\nことば ver.25：Supabase 2.24.0で未対応のpostgrest_client_retry引数を除去し、同期クライアント用の公開ClientOptionsへ修正。8秒タイムアウトは維持。新しい版で対応する場合だけ自動再試行を無効にする。旧版の再試行回数はライブラリ既定で、画面は既存3秒復帰処理で待ち続けない。メイン接続と教材登録の両方を同じ互換ヘルパーへ統一。requirements/Secrets/SQL変更不要。\n\nことば ver.24 起動・動作ログ修正\n・初期表示前の3132問台帳全件送信を撤去。教材登録は学習中のバックグラウンド処理へ移し、同じ版は重複実行を抑制。\n・DB通信の既定120秒＋自動再試行を、1リクエスト8秒・自動再試行なしへ変更。未送信の学習ログは既存outboxで再送。\n・初期応答が3秒来ない場合は端末内学習へ復帰。遅れて来た本人確認応答は進行中の問題を消さず、ホームへ戻ってから反映する。\n・未連携で実施した学習を別の学習者の履歴へ自動移動しない。未連携時はその状態を表示する。\n・設定の「動作ログを保存」からJSONを取得。最新1000件を端末内に保持（学習正本・未送信データとは別）。\n・iframe内起動、本人確認、履歴取得、台帳登録、操作→画面、チャレンジ開始、通信保存、エラー種別を記録。回答/名前/学習者ID/端末証明/認証トークン/URLは除外。\n・測定起点はiframe生成後。外部アプリアイコンのタップ、Streamlit起動待ち、iframe生成前はこのログだけでは計測できない。実機の総時間短縮は未確認。\n・再現試験：応答なしで旧版は初期化されない状態を再現し、新版は3秒後の端末内起動と問題開始、遅延応答時の学習維持、正常起動、ログ記録・出力導線を確認。\n・模擬サーバーでは初期本人確認処理の同期台帳登録呼出1→0、別スレッドの単一実行/全件処理を確認。通信速度の実測比較ではない。\n・既存3132問、内容別4/6/8/12問、メダル・音声・終了画面ボタン・DB構造・RLS・学習イベント仕様を維持。\n新しいSQL・Secrets・requirementsは不要。GitHubへはapp.pyにリネームして配置。\n\nことば ver.22 更新：内容別の問題数\n短い説明4問、論理/短文読解6問、言葉の使い方/ことわざ/慣用句/四字熟語8問、反対語/仲間分け/類義語/言葉の意味12問。全難易度共通。\n途中保存済みの実施は開始時の問題数で再開。既存履歴・メダル回数・問題3132問・音声を維持。\n満点金はその実施の全問正解で判定。苦手練習のデイリーメダルは従来どおり白。\nメニュー台帳は新しい教材版で問題数と仮目安を更新し、旧版を削除しない。既存問題ID・技能IDは維持。\nことば専用RPCの12問固定判定を可変化するSQLを対象 kotoba_app / keewulninyoeylgflshb へ適用。既存表・権限は変更しない。\nファイルはapp.py_ver.22.py、GitHubではapp.pyへリネーム。新しいSecrets/requirementsは不要。\n今回のテスト結果は完了時の報告に記載。以下は前版の連携仕様（固定12問という記述は今回の内容別問題数に置換して読む）。\n\nちょこまな（国語）ことば ver.20 — 記録・連携仕様と操作\n\n変更対象: lstm500/kokugo_kotoba の最新 app.py（ver.19）を2026-11-10 JSTに再取得し、作業元とSHA256一致を確認。\n参照のみ: 添付そろばん CLEAN-V171-DAILY-MEDAL-POPUP、lstm500/chokomana main。\n他リポジトリ、集約アプリのコード、問題3132問、既存採点、音声、年齢別表記、金メダル回数UIは変更しない。\n\n1. 配置・必要設定（実行順）\n1) 対象は kotoba_app / keewulninyoeylgflshb。共通catalog/events、ことば専用書込RPC、本人確認RPCは実DBに適用済み。\n   ver.20の苦手練習完了対応RPCも適用・ロールバック式実接続テスト済み。既存stampsを再作成しない。\n   通常、このDBで追加SQL実行は不要。--print-integration-sql は、この版のことば専用RPCの参照用SQLを出力する。\n   別プロジェクトや構造が違うDBに、そのまま実行しない。\n2) Streamlit Secrets の既存 SUPABASE_URL と SUPABASE_SERVICE_ROLE_KEY（又はSUPABASE_SECRET_KEY）を維持。\n   SUPABASE_URL="https://keewulninyoeylgflshb.supabase.co"\n   追加推奨 KOTOBA_APP_URL="https://<実際のことばアプリのURL>/"：台帳を初回公開するときに設定。\n   任意 CHOKOMANA_HUB_URL="https://chokomana-hkgx4uyxxezjtr2sj35jwj.streamlit.app/"：戻る先。上記が既定値。\n   公開キーは既定値内蔵。変更時のみ SUPABASE_PUBLISHABLE_KEY / SUPABASE_ANON_KEY。\n   APP_PASSWORD、共有固定CHOCOMANA_PROFILE_IDはこの版の連携には使用しない。\n3) この単体ファイルを app.py にリネームして、ことばリポジトリの既存ファイルと差し替える。\n   既存 requirements.txt（streamlit==1.51.0、supabase==2.24.0）は変更不要。\n4) ちょこまなからことばを開く。cm_launch はサーバーで検証して一度だけ消費し、URLから除去する。\n   直接開いた未連携端末でも学習は続けられる。連携状況は画面の保存状態に表示する。\n5) 確認時は12問完了し、保存確認後のポップアップと集約側の今日の成果を確認する。\n   左上の「ちょこまなへ」は別タブ。現在の問題を破棄せず、秘密や起動チケットを戻りURLへ付けない。\n\n台帳公開は既存DB権限に合わせてINSERT/重複無視。UPDATE権限は新しく要求しない。\n初回登録後にlaunch_urlを変更する場合は、管理者が当該kotobaメニュー行だけ更新する必要がある。\n例（URLは実URLへ置き換える。初回前ならこのSQLは不要）：\nUPDATE public.chokomana_learning_catalog\nSET payload=jsonb_set(payload,\'{launch_url}\',to_jsonb(\'https://<実際のことばアプリURL>/\'::text))\nWHERE source_app=\'kotoba\' AND entry_type=\'menu\' AND content_version=\'kotoba-6533318333403aa7\';\n\n2. 保存先と共通項目\n共通正本は既存 chokomana.learning.v1 / schema_version=1。\n先行共通仕様が整数ミリ秒を指定するため、その単位を優先。秒が必要なら *_ms / 1000.0、分なら /60000.0。\n日時はUTC ISO8601 Z、DBはtimestamptz。未取得はnull。0、falseと未知を混同しない。\nsource_app: text必須、kotoba固定（そろばんsoroban、図形geometry）。\nprofile_id: 検証済みUUIDのtext必須。未連携イベントは端末内だけnull、DBへ送らない。\nattempt_id: UUID必須、新しい12問の実施開始時だけ発行。途中再開・再送で維持。\ncategory_key: スタンプの既存text列。共通イベント/台帳のcategory_idが同じ識別子を表す。\nmenu_id: text必須、kotoba.<category_id>.<difficulty_id>。\nskill_id: 複数技能対応のskill_ids配列で保持。単一技能と誤認しない。\ndifficulty_id: beginner / intermediate / advanced。順序1/2/3、同じprogression_group_id内だけ比較。\ncontent_version: kotoba-6533318333403aa7、問題内容のハッシュ。表示年齢と選択肢シャッフルで変化しない。\n\npublic.chokomana_learning_catalog:\n schema_version int必須、source_app text必須、entry_type menu/skill/question必須、entry_id text必須、\n content_version text必須、payload jsonb必須、published_at DB生成。\n PK(source_app,entry_type,entry_id,content_version)。33メニュー、62技能、3132問題。\n メニューは名称、category_id、skill_ids、difficulty_id/order、12問、estimated_duration_ms、duration_basis=provisional、\n duration_rationale、next_menu_ids、prerequisite_skill_ids=null、age_min/max=null、launch_url、selection_instructions、supports_direct_launch=false。\n 教材の対象年齢・前提技能が未確認なので推測で設定しない。年齢設定は既存の表示漢字だけに使用。\n questionは正解仕様と教材スナップショットを含むサーバー専用行。公開SELECT不可。\n メニュー・技能のみ公開SELECT、学習履歴は本人のみ。既存RLSを緩和しない。\n\npublic.chokomana_learning_events（追記型正本）:\n schema_version int、event_id UUID PK、profile_id text、source_app text、app_version text、content_version text、\n attempt_id UUID、segment_id UUID、sequence int>0、occurred_at UTC、event_type text、payload jsonbは必須。\n occurrence_id UUID、question_id textは問題イベントで必須、実施全体イベントではnull可。\n received_at DB生成、event_hashはサーバーが正規化した本文のSHA256。\n UNIQUE(profile_id,source_app,segment_id,sequence)、同一出題枠のresponse_index、実施内のroot positionにも一意制約。\n 同じevent_idの異なる本文は拒否。訂正は既存行UPDATEではなく別イベントで参照する仕様。\n\npublic.chokomana_stamps（既存表維持）:\n profile_id,source_app,attempt_id,category_key,category_label,stamp_char,reading,difficulty,\n correct_count,total_count,grade,finished_at を保存。study_date/stamp_id/created_atは送らずDB生成。\n UNIQUE(profile_id,source_app,attempt_id)。正常完了1回1個、途中終了0個。\n チャレンジは既存の満点金基準を維持し、初回12/12=gold、それ以外white。銀・銅の新基準を追加しない。\n 苦手練習は既存の金メダル対象ではないので、12問完了時にwhite。既存金メダル回数へ加算しない。\n 各内容の漢字・ひらがな音読みはメニュー台帳で固定し、難易度で変えない。\n 保存確認までは「学習をやり切りました！」と保存中/未連携/失敗を表示。\n DBの本人用スタンプ行を確認したときだけ「デイリーメダルを獲得しました」。同じ実施の通知も重複抑制。\n\n既存 public.chocomana_state は保存先・JSON構造を保持し、cm_recorderだけ追加。revisionで競合検出。\n元の1500件履歴上限は維持するが、精密イベント正本と未送信outboxはこの上限で切り捨てない。\n旧family_defaultの行は削除も別UUIDへの自動移行もしない。所有者が不明な共有行を他児へ公開できないため。\n旧共有履歴を本人へ移すには、管理者が所有者を確認した別途移行が必要。\n\n3. 問題記録と評価の意味\nsession_started: メニュー・カテゴリ・難易度・設定スナップショット・mode・開始時刻。\nitem_presented: 出題順、安定したquestion_id、question_family_id、skill_ids、choice_order、出題可能時刻。\nresponse_submitted: response_id、response_index、実際の選択肢ID/自己確認、response_status、初回正誤、支援利用、回答所要ms。\nsupport_used: ヒント、正解、解説、例、読み直しを別種にし、初回回答の前/後を区別。\nsession_paused/resumed/ended: 休憩・再開・completed/abandoned等、最後の問題/回答参照。\nlearning_activity: 選択肢順の変更、読み上げ、結果振り返りなど実際に観測できた操作。\n同じ枠の再提出は同じoccurrence_idでresponse_indexを増加し、初回を上書きしない。\n通常UIには再回答・時間切れ・スキップの新しい操作を追加していない。未実施のイベントは作らない。\n短い説明は保護者/本人の確認を見分ける操作が既存UIにないため、assessment_method=legacy_unknown。\nそれを自動採点・客観的理解の証拠と扱わない。parent_helpは観測不能なのでnull。\n過去の答えの露出は全期間を確認できずanswer_exposed_before=null。無支援の断定をしない。\nfamilyは技能/問題形式のテンプレート、related_material_idは同じ表現や文章、passage_idは共有読解文。\n同一question_idの再出題、同じfamilyの別問題、同じ文章に依存する問題を区別できる。\n旧途中データを再開した場合はlegacy_importで欠損を示す。旧版で観測していない回答支援・時間は補完しない。\n旧途中データは開始や全問題の精密イベントが揃わず、スタンプ確定対象にならない場合がある。\n新しいチャレンジは通常どおり記録する。旧完了履歴を新しいスタンプとして再発行しない。\n\n4. 時間と当日の集計\n問題のDOM表示後からperformance.now()で整数msを計測。UTC開始終了の区間を並記する。\nthinking/feedback/explanation/reading_aloud/otherを区別。結果振り返りもactive、ホーム/休憩は除外。\nhidden、explicit_pause、blocking_waitを別記。無操作だけで考える時間を除外しない。\n非ブロック型のバックグラウンド保存中は学習可能なのでactiveを維持。同期処理が学習を妨げる場合だけblocking_wait。\n5秒ごと端末保存、通常15秒以上の間隔で送信。再描画で出題枠・初回時間をリセットしない。\n30秒を超える不明な前景停止や壁時計の飛び、再読込で観測不能な間はunknown、active_ms=null。\nブラウザのスケジューリング、OS休止、突然の終了で末尾数秒の記録が欠ける可能性がある。\nタブの休憩・非表示イベントを観測できた範囲は除外。終了通知が届かない場合、無理に完了や誤答にしない。\nWeb Locksとサーバー45秒リースで同一アプリ複数タブを抑制。衝突側の時間はunknown、二重加算しない。\nチャレンジ全経過時間はstarted～endedの差、実時間は有効active区間。中断でも区間を日次に含める。\n一日をAsia/Tokyoの0:00～翌0:00で切り、全source_appの有効active区間を重複除去して和集合の長さを集計。\nattemptの合計時間やメダル数から日次時間を足し直さない。event_idと(source_app,attempt_id)を保持する。\n認証JWT利用時はRPC chokomana_learning_day_time_v1(p_day date)がactive_msを返す。\n現在の同RPCのunknown_interval_countは発生日時の日で数えるため、複数日をまたぐ未知区間の各日件数には使わない。\n集約側は必要ならstart_at/end_atと対象日の交差で未知区間を数える。active時間の和集合は実DBで検証済み。\n\n5. 初期目安と実測\n初期目安は全てprovisional。通常120/180/240秒、論理180/300/420秒、読解240/420/600秒、説明240/360/480秒。\n学習者×source_app×menu_id×difficulty_id×content_version×settings_snapshot×modeを分ける。\nchokomana_learning_duration_estimates は未知区間のない有効な完了実施の直近10件、最低3件で中央値を返す。\nsample_count<3ではmeasured_estimate_available=false、measured_estimated_duration_ms=null。\n参考median_duration_msが返っても、確定した目安や標準時間として表示しない。\n全完了の所要時間と、回答だけの時間を混同しない。後から結果画面を見直す時間も区間として追記される。\n\n6. 集約側からの取得（今回そのコードは変更しない）\n・本人を検証した集約サーバーの既存接続、又は対応する本人のAuth JWT＋公開キーを使用。\n  serviceキーで任意URLのprofile_idを信用して照会しない。\nGET /rest/v1/chokomana_learning_catalog?source_app=eq.kotoba&entry_type=in.(menu,skill)\nGET /rest/v1/chokomana_learning_events?profile_id=eq.<検証済み本人UUID>&source_app=eq.kotoba&order=occurred_at,event_id\nGET /rest/v1/chokomana_stamps?profile_id=eq.<検証済み本人UUID>&source_app=eq.kotoba\nGET /rest/v1/chokomana_learning_response_facts?profile_id=eq.<本人UUID>&source_app=eq.kotoba\nGET /rest/v1/chokomana_learning_duration_estimates?profile_id=eq.<本人UUID>&source_app=eq.kotoba\n大量取得はページングし、event_idで重複排除。順不同到着をoccurred_atだけの増分カーソルで取りこぼさない。\nイベントの因果参照、response_index=1、parent_occurrence_id=null、教材版・設定を使って再構成する。\n同じ答え/同じ文章の暗記だけで習得とはしない。nullの支援/露出情報はfalseに変換しない。\nGitHubの現行集約版には台帳/イベントを読む処理が存在するが、ことばとの実デプロイ接続は未確認。\n現行集約のanswer_exposed_before=nullの扱い等は別途確認が必要。nullだけを根拠に苦手と断定しない。\n今回追加した戻りボタンは純粋なリンクで、集約側へ学習データを直接送らない。\n\n7. 識別・再送・保存範囲\n既存cm_launchは十分長い乱数、一回限り、有効期限、source_app=kotobaをサーバーで照合。\n端末用256bitランダム値をこのアプリのlocalStorageへ置き、DBにはSHA256(\'kotoba:\'+値)だけ保存。\n保存ごとにその対応を照合。profile_idだけのURLは本人確認に使用しない。別ドメインのlocalStorageは共有しない。\n同じブラウザで別児を使うには集約側で検証済みの別児チケットを発行する必要がある。\n今回子ども選択UIを追加しない。共有端末は児童ごとのブラウザプロフィールで分離する運用が確実。\nブラウザ変更・データ削除・別端末は自動復元できず、集約側の本人セッションから再度起動する。\n匿名Authは現設定で無効（確認済み）。単独利用の自動匿名連携を使う場合だけSupabase AuthでAnonymous Sign-insを有効化。\n集約の既存アカウント起動チケット経由では、この子アプリ独自の匿名ユーザー作成は不要。\n単独匿名IDと集約IDは自動で同一と見なさない。未連携履歴も後で別児に自動付け替えしない。\n\n端末IndexedDBのoutboxを学習者別に保持、利用不能ならlocalStorageへ退避。ACKのevent_idだけ削除。\n容量/期間による黙示的破棄はしない。保存容量の上限は端末依存、失敗時は警告しRAM保持＋再試行。\n永続保存が両方不可の場合はページを閉じると未送信データが失われ得る。成功とは表示しない。\n再送は同じID・同じ本文、最大100件/256KiB。失敗時は1秒～最大5分へバックオフし学習を止めない。\n端末の保存データ削除は未送信も失う。共有端末で他児のキューを新しいIDへ自動変換しない。\nスタンプと詳細はことばRPCの同一トランザクションで保存。遅れて届く前半イベントでも完了条件を再評価。\n詳細DBが一時使用不可でも既存状態保存を試し、イベントACKは返さず未送信を残す。\nDB結果の確認だけ失敗した場合も同じattempt_idでスタンプ確認を再試行する。\n\n8. 取得用コマンド（この配布ファイルだけで内容を取得できる）\npython app.py_ver.20.py --integration-help\npython app.py_ver.20.py --print-integration-sql\npython app.py_ver.20.py --print-catalog\n必要な実施のUUIDを確認後、ことばアプリのURLへ ?cm_export_attempt=<attempt_id> を付けると、本人確認後その実施の共通ログだけダウンロード可能。\n他児のIDを指定してもその履歴を返さない。デバイス証明や認証トークンはログ出力に含めない。\n\n9. テスト結果と未確認\n模擬: jsdom実DOM＋fake-indexeddbで12問、初回誤答後の再提出、ヒント/解説、休憩、hidden、読込後unknown、別児キュー、\n無操作思考、明示blocking_wait、読み上げ時間、複数タブ、ACK、メダル保存中/失敗/保存確認/重複通知抑止、戻るリンク、再読み込み時の識別再確認、3132問一致、満点金回数、音量・漢字表記の維持を確認。\nPython: 本人整合、自動採点の再検算、未知/無回答、時間整合、本文ハッシュ、初回分母を確認。\nStreamlit 1.51.0 AppTest: Secrets未設定でも例外なく既存コンポーネントを表示。\n実Supabase: 4完了実施＋中断、苦手練習白、初回11問白・再回答上書きなし、完了金、逆順到着、再送重複拒否、\n別児拒否、チケット再利用拒否、タブリース、RLS、正解台帳非公開、直近中央値、東京0時/アプリ間時間重複を検証。\nテストは全てロールバック、テスト履歴残存0件。メニュー台帳の本番公開はデプロイ後に行う。\n未確認: 実ブラウザでの視覚表示と実音声、Streamlit本番→Supabaseの全経路、実集約アプリからの起動・表示、\n実機休止/クラッシュ/ネットワーク断の全組合せ、匿名Auth有効化後の新規認証。\n過去の任意履歴から能力は断定しない。今回AI評価・計画生成は実装していない。\n\n前回、台帳UPDATE権限と未知区間日次カウントの補助調整はクレジット不足による自動承認処理失敗で未適用。\nこの版は既存INSERT権限で動作させるため前者不要。後者の制約は上記に明記し、未適用の調整を実行済みと扱わない。\n'
EVENT_TYPES = {'session_started','item_presented','response_submitted','support_used','learning_activity','time_interval_closed','session_paused','session_resumed','session_ended','legacy_import','record_corrected'}
PHASES = {'prompt','thinking','answering','feedback','explanation','exploration','reading_aloud','other'}

class IntegrationBusy(RuntimeError):
    pass

def _uuid(value, nullable=False):
    if value is None and nullable: return None
    try: return str(uuid.UUID(str(value)))
    except Exception: raise ValueError('UUIDの形式が正しくありません。') from None

def _timestamp(value):
    if not isinstance(value,str) or not value.endswith('Z'): raise ValueError('日時はUTC・Z付きで指定してください。')
    datetime.fromisoformat(value.replace('Z','+00:00'))
    return value

def _integer(value,low=0,high=86_400_000,nullable=False):
    if nullable and value is None:return None
    if type(value) is not int or not low<=value<=high:raise ValueError('記録の整数値が範囲外です。')
    return value

def _nullable_bool(value):
    if value is not None and type(value) is not bool:raise ValueError('正誤または支援の形式が正しくありません。')
    return value

def normalize_events(events,profile,older_catalogs=None):
    if not isinstance(events,list) or len(events)>100:raise ValueError('イベントは100件以下で送信してください。')
    if len(json.dumps(events,ensure_ascii=False).encode())>262144:raise ValueError('送信するイベントが大きすぎます。')
    out=[]
    for raw in events:
        if not isinstance(raw,dict) or raw.get('schema_version')!=1 or raw.get('source_app')!=SOURCE_APP:raise ValueError('共通ログの版またはアプリが一致しません。')
        if raw.get('profile_id')!=profile:raise PermissionError('学習者の記録が一致しません。')
        e={k:raw.get(k) for k in ('schema_version','event_id','profile_id','source_app','app_version','content_version','attempt_id','occurrence_id','question_id','segment_id','sequence','occurred_at','event_type','payload')}
        for k in ('event_id','attempt_id','segment_id'):e[k]=_uuid(e[k])
        e['occurrence_id']=_uuid(e['occurrence_id'],True);_integer(e['sequence'],1,2_147_483_647);_timestamp(e['occurred_at'])
        if e['event_type'] not in EVENT_TYPES or not isinstance(e['payload'],dict) or (e['content_version']!=CONTENT_VERSION and e['content_version'] not in (older_catalogs or {})) or len(str(e['app_version']))>32:raise ValueError('イベントの形式が不正です。')
        p=json.loads(json.dumps(e['payload'],ensure_ascii=False));e['payload']=p
        if len(json.dumps(p,ensure_ascii=False).encode())>16384:raise ValueError('イベント本文が大きすぎます。')
        catalog=(older_catalogs or {}).get(e['content_version']);question_lookup={r['entry_id']:r['payload'] for r in catalog if r['entry_type']=='question'} if catalog is not None else QUESTION_BY_ID
        q=question_lookup.get(e['question_id']) if e['question_id'] else None
        if e['question_id'] is not None and q is None:raise ValueError('教材にない問題です。')
        if e['event_type']=='session_started':
            menus={r['entry_id']:r['payload'] for r in (catalog if catalog is not None else CATALOG_ROWS) if r['entry_type']=='menu'}
            menu=menus.get(p.get('menu_id'))
            if not menu or p.get('category_id')!=menu['category_id'] or p.get('difficulty_id')!=menu['difficulty_id'] or p.get('planned_question_count') not in menu['question_count_options']:raise ValueError('メニューの記録が一致しません。')
            if p.get('mode') not in {'challenge','review','learn','drill','reading_aloud','other'}:raise ValueError('モードが不正です。')
        elif e['event_type']=='item_presented':
            if not q or not e['occurrence_id']:raise ValueError('出題枠がありません。')
            _integer(p.get('position'),1,12);_integer(p.get('retry_index'),0,10000)
            _uuid(p.get('parent_occurrence_id'),True)
            if p.get('presentation_kind') not in {'new','scheduled_repeat','retry'}:raise ValueError('出題種別が不正です。')
            if p.get('parent_occurrence_id') is not None and p.get('presentation_kind')!='retry':raise ValueError('再挑戦の親参照が不正です。')
            if sorted(p.get('choice_order') or [])!=sorted(q['choice_ids']):raise ValueError('選択肢の記録が一致しません。')
            p.update(question_family_id=q['question_family_id'],skill_ids=q['skill_ids'],related_material_id=q['related_material_id'],passage_id=q['passage_id'],question_content_version=e['content_version'])
            _nullable_bool(p.get('answer_exposed_before'))
        elif e['event_type']=='response_submitted':
            if not q or not e['occurrence_id']:raise ValueError('回答する問題がありません。')
            _uuid(p.get('response_id'));_integer(p.get('response_index'),1,10000)
            if p.get('response_status') not in {'answered','dont_know','skipped','timed_out'}:raise ValueError('回答状態が不正です。')
            if p.get('input_method') not in {'keyboard','keypad','choice','speech','self_check','other'}:raise ValueError('入力方式が不正です。')
            if p.get('speech_status') not in {'not_used','recognized','recognition_failed','uncertain','corrected'}:raise ValueError('音声認識状態が不正です。')
            p['assessment_method']=q['assessment_method']
            if p['response_status']!='answered':p['is_correct']=None
            elif q['assessment_method']=='automatic':
                cid=(p.get('response_value') or {}).get('choice_id')
                if cid not in q['choice_ids']:raise ValueError('提出された選択肢が不正です。')
                p['is_correct']=cid==q['correct_answer_spec']['choice_id'];p['correctness_basis']='catalog_exact_choice_v1'
            else:
                confirmed=(p.get('response_value') or {}).get('confirmed');_nullable_bool(confirmed)
                p['is_correct']=confirmed;p['correctness_basis']='self_or_parent_confirmation';p['evaluator_candidates']=['self','parent']
            support=p.get('support_before_response')
            if not isinstance(support,dict):raise ValueError('支援の記録がありません。')
            for k in ('hint_count','max_hint_step'):_integer(support.get(k),0,10000,True)
            for k in ('explanation_seen','answer_seen','worked_example_seen','parent_help'):_nullable_bool(support.get(k))
            _integer(p.get('answer_latency_ms'),0,86_400_000,True)
            if p.get('timing_quality') not in {'complete','partial','estimated','unknown'}:raise ValueError('時間の品質が不正です。')
        elif e['event_type']=='support_used':
            if p.get('support_type') not in {'hint','explanation','answer','worked_example','parent','replay'}:raise ValueError('支援種別が不正です。')
            _nullable_bool(p.get('before_first_response'));_nullable_bool(p.get('answer_revealing'))
        elif e['event_type']=='time_interval_closed':
            if p.get('phase') not in PHASES or p.get('timing_quality') not in {'complete','partial','estimated','unknown'}:raise ValueError('時間区間の形式が不正です。')
            _timestamp(p.get('start_at'));_timestamp(p.get('end_at'));_uuid(p.get('window_instance_id'))
            elapsed=_integer(p.get('elapsed_ms'),0,86_400_000,True);active=_integer(p.get('active_ms'),0,86_400_000,True)
            exclusions=p.get('excluded_ms')
            if not isinstance(exclusions,dict):raise ValueError('除外時間の記録が不正です。')
            values=[_integer(exclusions.get(k),0,86_400_000,True) for k in ('hidden','explicit_pause','blocking_wait')]
            if p['timing_quality']=='complete' and (elapsed is None or active is None or any(v is None for v in values) or active+sum(values)!=elapsed):raise ValueError('区間の時間が一致しません。')
            if p['end_at']<p['start_at']:raise ValueError('区間の時刻が逆です。')
        elif e['event_type']=='session_ended':
            if p.get('status') not in {'completed','abandoned','interrupted','timed_out'}:raise ValueError('終了状態が不正です。')
            for k in ('planned_question_count','presented_count','answered_count'):_integer(p.get(k),0,10000)
            if p.get('status')=='completed' and (p.get('planned_question_count') not in (4,6,8,12) or p.get('answered_count')!=p.get('planned_question_count')):raise ValueError('完了した回答数が不正です。')
        e['event_hash']=hashlib.sha256(json.dumps(e,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()).hexdigest();out.append(e)
    return out

def device_hash(device):
    if not isinstance(device,str) or not re.fullmatch('[a-f0-9]{64}',device):raise PermissionError('端末の識別情報が不正です。')
    return hashlib.sha256((SOURCE_APP+':'+device).encode()).hexdigest()

def verify_anonymous_token(url,public_key,token):
    if not isinstance(token,str) or len(token)>8192:raise PermissionError('匿名認証を確認できません。')
    req=urllib.request.Request(url+'/auth/v1/user',headers={'apikey':public_key,'Authorization':'Bearer '+token})
    with urllib.request.urlopen(req,timeout=8) as response:user=json.load(response)
    if user.get('is_anonymous') is not True:raise PermissionError('匿名利用者として確認できません。')
    return _uuid(user['id'])

def resolve_identity(client,device,ticket=None,access_token=None,public_key=DEFAULT_PUBLIC_KEY):
    dh=device_hash(device)
    if ticket:
        if not isinstance(ticket,str) or not 20<=len(ticket)<=256:raise PermissionError('起動チケットの形式が不正です。')
        try:
            result=client.rpc('chokomana_claim_learning_device',{'p_source_app':SOURCE_APP,'p_device_hash':dh,'p_ticket_hash':hashlib.sha256(ticket.encode()).hexdigest()}).execute().data
            if result:return _uuid(result)
        except Exception:
            # Reopening an already redeemed link is safe only with its bound capability.
            rows=client.table('chokomana_device_links').select('profile_id').eq('device_hash',dh).eq('source_app',SOURCE_APP).limit(1).execute().data
            if rows:return _uuid(rows[0]['profile_id'])
            raise PermissionError('起動リンクを確認できません。ちょこまなからもう一度開いてください。') from None
    rows=client.table('chokomana_device_links').select('profile_id').eq('device_hash',dh).eq('source_app',SOURCE_APP).limit(1).execute().data
    if rows:return _uuid(rows[0]['profile_id'])
    if not access_token:return None
    profile=verify_anonymous_token(PUBLIC_URL,public_key,access_token)
    client.table('chokomana_device_links').upsert({'device_hash':dh,'source_app':SOURCE_APP,'profile_id':profile},on_conflict='device_hash',ignore_duplicates=True).execute()
    rows=client.table('chokomana_device_links').select('profile_id').eq('device_hash',dh).eq('source_app',SOURCE_APP).limit(1).execute().data
    if len(rows)!=1 or str(rows[0]['profile_id'])!=profile:raise PermissionError('端末と学習者の対応を確認できません。')
    return profile

def publish_catalog(client,launch_url=None):
    # Questions and answer specifications stay behind service-only access.
    for start in range(0,len(CATALOG_ROWS),200):
        rows=json.loads(json.dumps(CATALOG_ROWS[start:start+200],ensure_ascii=False))
        if launch_url:
            for r in rows:
                if r['entry_type']=='menu':r['payload']['launch_url']=launch_url
        client.table('chokomana_learning_catalog').upsert(rows,on_conflict='source_app,entry_type,entry_id,content_version',ignore_duplicates=True).execute()

@st.cache_resource
def _catalog_workers():
    import threading
    return {'lock':threading.Lock(),'states':{}}

def catalog_ready(url,key,version,launch_url):
    import threading
    registry=_catalog_workers();token=hashlib.sha256((url+key+version+(launch_url or '')).encode()).hexdigest()
    with registry['lock']:
        entry=registry['states'].get(token)
        if entry and entry['status']=='ready':return True
        if entry and (entry['status']=='running' or _boot_time.monotonic()<entry.get('retry_at',0)):return False
        entry={'status':'running','started':_boot_time.monotonic()};registry['states'][token]=entry
    def work():
        try:
            from supabase import ClientOptions
            client=create_client(url,key,options=_supabase_options())
            ordered=sorted(CATALOG_ROWS,key=lambda r:{'menu':0,'skill':1,'question':2}[r['entry_type']])
            markers=[ordered[0]['entry_id'],ordered[-1]['entry_id']]
            existing=client.table('chokomana_learning_catalog').select('entry_id').eq('source_app',SOURCE_APP).eq('content_version',version).in_('entry_id',markers).execute().data
            if {r['entry_id'] for r in existing}!=set(markers):
                for i in range(0,len(ordered),200):
                    rows=json.loads(json.dumps(ordered[i:i+200],ensure_ascii=False))
                    if launch_url:
                        for r in rows:
                            if r['entry_type']=='menu':r['payload']['launch_url']=launch_url
                    client.table('chokomana_learning_catalog').upsert(rows,on_conflict='source_app,entry_type,entry_id,content_version',ignore_duplicates=True).execute()
            with registry['lock']:entry.update(status='ready',duration_ms=round((_boot_time.monotonic()-entry['started'])*1000))
        except Exception as exc:
            with registry['lock']:entry.update(status='retry',error_type=type(exc).__name__,retry_at=_boot_time.monotonic()+60,duration_ms=round((_boot_time.monotonic()-entry['started'])*1000))
    threading.Thread(target=work,name='kotoba-catalog',daemon=True).start();return False

def _boot_measure(stage,fn):
    started=_boot_time.perf_counter();ok=False;error_type=None;error_code=None
    try:
        value=fn();ok=True;return value
    except Exception as exc:
        error_type=type(exc).__name__;code=str(getattr(exc,'code',''))
        error_code=code if re.fullmatch(r'[A-Za-z0-9_]{1,24}',code) else None
        raise
    finally:
        rows=st.session_state.setdefault('cm_boot_diagnostics',[])
        rows.append({'id':str(uuid.uuid4()),'stage':stage,'duration_ms':round((_boot_time.perf_counter()-started)*1000,2),'ok':ok,'error_type':error_type,'error_code':error_code})
        del rows[:-100]

def commit_events(client,profile,device,writer,state,revision,events,active):
    if not isinstance(events,list) or len(events)>100:raise ValueError('イベントは100件以下で送信してください。')
    versions={e.get('content_version') for e in events if isinstance(e,dict)}-{CONTENT_VERSION}
    if len(versions)>5:raise ValueError('教材の版が多すぎます。')
    older={}
    for version in versions:
        if not isinstance(version,str) or not re.fullmatch(r'kotoba-[a-f0-9]{16}',version):raise ValueError('教材の版が不正です。')
        ids={e.get('question_id') for e in events if e.get('content_version')==version and e.get('question_id')}
        ids.update(e.get('payload',{}).get('menu_id') for e in events if e.get('content_version')==version and e.get('event_type')=='session_started')
        ids.discard(None)
        rows=client.table('chokomana_learning_catalog').select('entry_id,entry_type,payload').eq('source_app',SOURCE_APP).eq('content_version',version).in_('entry_id',list(ids)).execute().data if ids else [{'entry_id':'version-marker','entry_type':'skill','payload':{}}]
        if not rows:raise ValueError('過去の教材台帳が見つかりません。記録を端末に保持します。')
        older[version]=rows
    canonical=normalize_events(events,profile,older)
    if resolve_identity(client,device)!=profile:raise PermissionError('学習者が切り替わりました。')
    try:
        result=client.rpc('chokomana_commit_learning_events_v1',{'p_device_hash':device_hash(device),'p_writer_id':_uuid(writer),'p_expected_revision':revision,'p_state':state,'p_events':canonical,'p_active':bool(active)}).execute()
        if result.data is None:raise ValueError('保存結果を確認できません。')
        return int(result.data),[e['event_id'] for e in canonical]
    except Exception as exc:
        if getattr(exc,'code',None)=='40001' or 'state revision conflict' in str(exc):raise SaveConflict('別の画面で更新されました。最新の記録を読み込んでください。') from None
        if getattr(exc,'code',None)=='55P03' or 'another learning tab' in str(exc):raise IntegrationBusy('別のタブで学習中です。このタブの詳細ログは端末内で待機しています。') from None
        raise

def export_session_events(client,device,attempt_id):
    profile=resolve_identity(client,device)
    if not profile:raise PermissionError('学習者の確認が必要です。')
    return client.table('chokomana_learning_events').select('*').eq('profile_id',profile).eq('source_app',SOURCE_APP).eq('attempt_id',_uuid(attempt_id)).order('occurred_at').order('sequence').execute().data

def secret(name,default=''):
    try:return str(st.secrets.get(name,default)).strip()
    except Exception:return default

def confirmed_medals(client, profile, attempt_ids):
    ids = list(dict.fromkeys(_uuid(x) for x in attempt_ids[:20])) if isinstance(attempt_ids,list) else []
    if not ids:return []
    return client.table('chokomana_stamps').select('attempt_id,category_key,category_label,stamp_char,reading,difficulty,correct_count,total_count,grade,finished_at').eq('profile_id',profile).eq('source_app',SOURCE_APP).in_('attempt_id',ids).execute().data

def hub_url():
    from urllib.parse import urlsplit
    value=secret('CHOKOMANA_HUB_URL','https://chokomana-hkgx4uyxxezjtr2sj35jwj.streamlit.app/')
    try:
        p=urlsplit(value)
        if p.scheme=='https' and p.hostname and not p.username and not p.password and not p.query and not p.fragment:return value
    except ValueError:pass
    return 'https://chokomana-hkgx4uyxxezjtr2sj35jwj.streamlit.app/'

# Optional unit launch: only a consumed, non-expired ticket belonging to the verified
# learner can supply an assignment. A raw profile/menu query parameter is never trusted.
def cm_capture_plan_ticket(state):
    ticket = st.query_params.get('cm_launch')
    if isinstance(ticket,str) and 20 <= len(ticket) <= 256:
        digest = hashlib.sha256(ticket.encode()).hexdigest()
        if state.get('_cm_plan_fingerprint') != digest:
            state['_cm_plan_fingerprint'] = digest
            state['_cm_plan_ticket'] = ticket
            state.pop('_cm_plan_assignment',None)


def cm_verified_plan_assignment(state, profile, source, rows_reader):
    import uuid,datetime
    if not profile:
        return None
    cached = state.get('_cm_plan_assignment')
    if cached and cached.get('_profile') == str(profile):
        return {k:v for k,v in cached.items() if k!='_profile'}
    ticket = state.get('_cm_plan_ticket')
    if not ticket:
        return None
    params={'ticket_hash':'eq.'+hashlib.sha256(ticket.encode()).hexdigest(),
        'profile_id':'eq.'+str(profile),'source_app':'eq.'+source,
        'expires_at':'gt.'+datetime.datetime.now(datetime.timezone.utc).isoformat(),
        'select':'plan_item_id,menu_id,content_version,launch_mode,used_at','limit':'1'}
    try:
        rows = rows_reader(params)
    except Exception:
        return None
    if not isinstance(rows,list) or len(rows)!=1 or not rows[0].get('used_at') or not rows[0].get('plan_item_id'):
        return None
    row=rows[0]
    try:
        item=str(uuid.UUID(row['plan_item_id']))
    except (ValueError,TypeError,AttributeError):
        return None
    menu=row.get('menu_id'); version=row.get('content_version')
    if not isinstance(menu,str) or not menu.startswith(source+(':' if source=='soroban' else '.')) or len(menu)>160:
        return None
    if not isinstance(version,str) or len(version)>160:
        return None
    mode=row.get('launch_mode')
    if mode not in ('learn','challenge','review','reading_aloud'):
        return None
    out={'plan_item_id':item,'menu_id':menu,'content_version':version,'mode':mode,
         'nonce':state['_cm_plan_fingerprint'],'_profile':str(profile)}
    state['_cm_plan_assignment']=out
    state.pop('_cm_plan_ticket',None)
    return {k:v for k,v in out.items() if k!='_profile'}

def main():
    st.set_page_config(page_title='ちょこまな（国語） - ことば',page_icon='📖',layout='wide')
    st.markdown('<style>.stApp{background:#f7f5ef}.block-container{padding:0.5rem!important;max-width:1180px!important}header[data-testid=stHeader]{display:none}</style>',unsafe_allow_html=True)
    url=secret('SUPABASE_URL',PUBLIC_URL);key=secret('SUPABASE_SERVICE_ROLE_KEY') or secret('SUPABASE_SECRET_KEY')
    public_key=secret('SUPABASE_PUBLISHABLE_KEY') or secret('SUPABASE_ANON_KEY') or DEFAULT_PUBLIC_KEY
    configured=url.rstrip('/')==PUBLIC_URL and bool(key)
    client=db_client(url,key) if configured else None
    if st.query_params.get('cm_launch'):st.session_state['cm_launch_pending']=str(st.query_params['cm_launch'])
    ticket=st.session_state.get('cm_launch_pending');fingerprint=hashlib.sha256(ticket.encode()).hexdigest()[:16] if ticket else None
    cm_capture_plan_ticket(st.session_state)
    context=st.session_state.get('cm_context')
    args={'hub_url':hub_url(),'bootstrap':not bool(context),'launch_fingerprint':fingerprint,'auth_config':{'url':PUBLIC_URL,'key':public_key}}
    if context:
        args.update(context)
        if context.get('linked') and client:
            def plan_rows(p):
                q=client.table('chokomana_launch_tickets').select(p['select'])
                for k in ('ticket_hash','profile_id','source_app'):q=q.eq(k,p[k][3:])
                return q.gt('expires_at',p['expires_at'][3:]).limit(1).execute().data
            args['plan_launch']=_boot_measure('plan_launch_lookup',lambda:cm_verified_plan_assignment(st.session_state,context['profile_id'],'kotoba',plan_rows))
        registry=_catalog_workers();token=hashlib.sha256((url+key+CONTENT_VERSION+secret('KOTOBA_APP_URL')).encode()).hexdigest()
        with registry['lock']:
            entry=registry['states'].get(token,{})
            args['catalogue_status']={k:entry[k] for k in ('status','duration_ms','error_type') if k in entry}
        args['initial']=st.session_state.get('cloud_state',context['initial'])
        args['revision']=st.session_state.get('revision',context['revision'])
        export_id=st.query_params.get('cm_export_attempt')
        if export_id and context['linked']:
            try:st.download_button('この学習の共通ログを保存',json.dumps(export_session_events(client,st.session_state['cm_device'],export_id),ensure_ascii=False,indent=2),file_name='kotoba_learning_events.json',mime='application/json')
            except Exception:st.info('指定した学習のログを取得できません。')
    args['server_diagnostics']=st.session_state.get('cm_boot_diagnostics',[])
    args['server_diagnostics']=args['server_diagnostics']+[{'id':'render-'+str(_BOOT_STARTED),'stage':'python_to_component','duration_ms':round((_boot_time.perf_counter()-_BOOT_STARTED)*1000,2),'ok':True}]
    event=component(FRONTEND)(**args,ack=st.session_state.get('ack'),key='chocomana_board_'+hashlib.sha256(FRONTEND.encode()).hexdigest()[:16],default=None)
    if not isinstance(event,dict):return
    if event.get('action')=='hello':
        hello_id=event.get('hello_id')
        if hello_id and hello_id==st.session_state.get('cm_processed_hello'):return
        st.session_state['cm_processed_hello']=hello_id
        device=event.get('device');device_hash(device);_uuid(event.get('writer'))
        profile=None;error=None;need_anon=False
        if client:
            try:profile=_boot_measure('identity_lookup',lambda:resolve_identity(client,device,ticket,event.get('access_token'),public_key));need_anon=profile is None
            except Exception as exc:error='学習者の連携を確認できません。端末内の記録で学習できます。'
        local_id='local:'+hashlib.sha256(device.encode()).hexdigest()[:32]
        cache=event.get('cache') if isinstance(event.get('cache'),dict) else {}
        state={'config':{'count':12,'age':5,'voice':False,'auto':False},'records':[],'session':None};revision=None
        linked=bool(profile)
        if profile:
            try:state,revision=_boot_measure('history_load',lambda:load_state(client,profile))
            except Exception:linked=False;error='履歴の取得に失敗しました。端末内の記録で学習できます。'
        cache_matches=cache.get('profile_id')==(profile or local_id)
        if cache_matches and isinstance(cache.get('state'),dict):
            try:
                candidate=validate_state(cache['state'])
                if not linked or cache.get('revision')==revision:state=candidate
            except Exception:pass
        if profile and linked:
            catalog_ready(url,key,CONTENT_VERSION,secret('KOTOBA_APP_URL'))
            # Catalogue registration is deferred until learning starts; never block initial display.
            st.session_state.pop('cm_launch_pending',None)
            if 'cm_launch' in st.query_params:del st.query_params['cm_launch']
        st.session_state['cm_context']={'identity_ready':True,'linked':linked,'profile_id':profile if linked else local_id,'revision':revision,'initial':state,'need_anonymous':need_anon and not error,'integration_message':error or ('Supabase 接続済み' if linked else '端末内に保存（ちょこまな連携は未接続）')}
        st.session_state['cm_device']=device;st.session_state['cm_writer']=event['writer'];st.session_state['cloud_state']=state;st.session_state['revision']=revision;st.session_state['processed_seq']=0;st.session_state['ack']=None
        st.rerun()
    if not context:return
    seq=event.get('seq')
    if type(seq) is not int or seq<=st.session_state.get('processed_seq',0):return
    profile=context['profile_id'];state=event.get('state');ack={'seq':seq,'profile_id':profile,'ok':False,'integration_ok':False}
    try:
        state=validate_state(state)
        if not context['linked']:
            ack.update(ok=True,local_only=True,message='端末内に保存（連携未接続）')
        else:
            if event.get('device')!=st.session_state['cm_device'] or event.get('profile_id')!=profile:raise PermissionError('学習者を確認できません。')
            try:
                if not catalog_ready(url,key,CONTENT_VERSION,secret('KOTOBA_APP_URL')):raise RuntimeError('catalogue preparation pending')
                revision,saved_ids=_boot_measure('learning_save',lambda:commit_events(client,profile,event['device'],event.get('writer'),state,st.session_state['revision'],event.get('events',[]),event.get('active',False)))
                ack.update(ok=True,integration_ok=True,revision=revision,saved_event_ids=saved_ids)
                try:ack['saved_medals']=confirmed_medals(client,profile,event.get('medal_attempt_ids',[]))
                except Exception:ack['medal_receipt_pending']=True
            except (SaveConflict,IntegrationBusy,PermissionError,ValueError):raise
            except Exception:
                # New logging tables/RPC unavailable: retain original state saving,
                # keep the durable event outbox, and do not report integration success.
                if resolve_identity(client,event['device'])!=profile:raise PermissionError('学習者を確認できません。')
                revision=_boot_measure('state_save',lambda:save_state(client,profile,state,st.session_state['revision']))
                ack.update(ok=True,revision=revision,message='履歴は保存済み。詳細ログは端末内で未送信です。')
            st.session_state['revision']=ack['revision'];st.session_state['cloud_state']=state
    except SaveConflict as exc:
        latest,rev=load_state(client,profile);ack.update(conflict=True,latest=latest,message=str(exc));st.session_state['revision']=rev
    except IntegrationBusy as exc:ack.update(busy=True,message=str(exc))
    except Exception:ack.update(message='保存を確認できません。端末内の未送信記録を保持しています。')
    st.session_state['processed_seq']=seq;st.session_state['ack']=ack
    st.rerun()


if __name__ == "__main__":
    if "--print-integration-sql" in sys.argv:print(INTEGRATION_SQL)
    elif "--integration-help" in sys.argv:print(INTEGRATION_HELP)
    elif "--print-catalog" in sys.argv:print(json.dumps(CATALOG_ROWS,ensure_ascii=False,indent=2))
    else:main()
